'use strict';
const el=id=>document.getElementById(id);
const icons={mail:'<rect x="3" y="5" width="18" height="14" rx="3"/><path d="m4 7 8 6 8-6"/>',note:'<rect x="4" y="3" width="16" height="18" rx="3"/><path d="M8 8h8M8 12h8M8 16h5"/>',play:'<path d="m9 5 11 7-11 7z"/>',pause:'<path d="M8 5h3v14H8zM15 5h3v14h-3z"/>',layout:'<rect x="3" y="4" width="18" height="16" rx="3"/><path d="M10 4v16M10 10h11"/>',search:'<circle cx="10" cy="10" r="6"/><path d="m15 15 5 5"/>',compose:'<path d="M12 4H5a2 2 0 0 0-2 2v13a2 2 0 0 0 2 2h13a2 2 0 0 0 2-2v-7M17 3l4 4-10 10H7v-4z"/>',star:'<path d="m12 3 3 6 7 1-5 5 1 7-6-3-6 3 1-7-5-5 7-1z"/>',archive:'<path d="M4 8h16v12H4zM3 4h18v4H3zM10 12h4"/>',back:'<path d="m14 5-7 7 7 7"/>',reply:'<path d="m9 5-6 5 6 5M3 10h9c6 0 9 4 9 9"/>',file:'<path d="M7 3h7l5 5v13H5V3zM14 3v6h5M8 13h8M8 17h5"/>',next:'<path d="m5 5 10 7-10 7zM18 5v14"/>',previous:'<path d="m19 5-10 7 10 7zM6 5v14"/>',check:'<path d="m5 12 5 5L20 7"/>'};
const icon=name=>`<svg viewBox="0 0 24 24" aria-hidden="true">${icons[name]||icons.note}</svg>`;
const escapeHTML=value=>String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const storageKey='duo-studio-examples-v1';
const initialNotes=[{id:'launch',title:'A little more room.',text:'One task. Two displays.\n\nA wider canvas should make the current task easier: keep the inbox beside a conversation, leave a draft in reach, and let the content breathe.',checks:[{text:'Keep the selected message when space changes',done:true},{text:'Preserve this draft when the window resizes',done:false},{text:'Keep every action reachable',done:false}]},{id:'review',title:'Design review',text:'Tuesday · Product & engineering\n\nStart with a compact layout that feels complete. Add a detail pane when there is enough room. Keep typography and tap targets comfortable.',checks:[{text:'Review compact navigation',done:true},{text:'Try keyboard focus through the controls',done:false}]},{id:'ideas',title:'Ideas for the next build',text:'A reading list with the article always in view.\nA player with a queue beside the artwork.\nAn editor that keeps the same thought open.',checks:[]}];
let model={app:'mail',selectedMail:'mira',selectedNote:'launch',mailFilter:'inbox',read:[],starred:[],archived:[],sent:[],notes:structuredClone(initialNotes),largeText:false,bounds:false};
function restore(){try{const data=JSON.parse(localStorage.getItem(storageKey));if(data&&Array.isArray(data.notes)&&data.notes.every(n=>typeof n.id==='string'&&typeof n.title==='string'&&typeof n.text==='string'&&Array.isArray(n.checks))&&['mail','notes','media','layout'].includes(data.app)){model={...model,...data};}}catch{}}
restore();
let detailOpen=Boolean(model.detailOpen),searchText='',toastTimer;
const mail=[
 {id:'mira',name:'Mira Chen',initials:'MC',color:'',time:'9:41 AM',subject:'A little more room for the good stuff.',preview:'The next chapter of our workspace is ready.',tag:'PRODUCT & DESIGN',paragraphs:['Hey Alex,','The new workspace is ready for a closer look. Open your inbox and you’ll see the conversation beside it — <strong>just enough room to keep the context.</strong>','Try narrowing the browser window while reading this message. The detail view should stay with you, with a clear way back to your inbox.','I left the review notes below. Add a thought, check off an item, and pick up right where you left off.','See you at the review,<br><strong>Mira</strong>']},
 {id:'leo',name:'Leo Martin',initials:'LM',color:'teal',time:'9:18 AM',subject:'Friday’s listening room',preview:'A quiet soundtrack for a focused morning.',tag:'OFF THE CLOCK',paragraphs:['Morning Alex,','I made a tiny listening room for the demo. It has an original ambient loop and a queue you can actually use.','Open <strong>Media</strong> below, hit play, and try the seek control. The audio begins only when you tap Play.','Hope it makes the next code review a little calmer.<br><strong>Leo</strong>']},
 {id:'ava',name:'Ava Patel',initials:'AP',color:'peach',time:'Yesterday',subject:'A good compact layout is the starting point',preview:'A few things to check before we ship.',tag:'ENGINEERING',paragraphs:['Hi Alex,','The compact version should have the same useful actions as the expanded one. A second pane is a convenience; it should never hide a feature.','For the next pass: keep a clear back path, preserve the current selection, and test long text.','The <strong>Layout</strong> tab reports the web viewport directly. Its pane breakpoint is our example’s content budget, not an iOS size class.','Thanks,<br><strong>Ava</strong>']},
 {id:'noah',name:'Noah Williams',initials:'NW',color:'blue',time:'Yesterday',subject:'Notes from the prototype review',preview:'Small details that make this feel finished.',tag:'DESIGN REVIEW',paragraphs:['Alex,','A few details from today: soften the dividers, make the selected row easy to find, and keep the primary action in the same place.','The best part of a larger display is being able to keep your train of thought. Let’s make that the first thing people notice.','I added a checklist in <strong>Notes</strong> so we can work through it together.','— Noah']},
 {id:'studio',name:'Studio team',initials:'ST',color:'',time:'Monday',subject:'Your workspace, in every size',preview:'Four small examples. Plenty to explore.',tag:'WELCOME TO DUO STUDIO',paragraphs:['Welcome in.','This is a small set of interactive web examples: read and organize sample messages, write notes, play a soundtrack, and inspect the layout.','Everything is local to this browser. Messages saved to Sent stay in the demo; they are never emailed.','Start anywhere. There is no right order.']}];
const tracks=[{title:'Stillwater',artist:'Duo Studio · Ambient studies',short:'Ambient studies',duration:16,rate:1},{title:'Morning light',artist:'Duo Studio · Slow mornings',short:'Slow mornings',duration:20,rate:.8},{title:'After the rain',artist:'Duo Studio · Quiet hours',short:'Quiet hours',duration:24,rate:2/3}];
let trackIndex=0;
const audio=el('demo-audio');
let generatedAudioUrl;
function prepareAudio(){
 if(generatedAudioUrl)return;
 const rate=22050,length=16,samples=rate*length,buffer=new ArrayBuffer(44+samples*2),view=new DataView(buffer);
 const text=(offset,value)=>{for(let i=0;i<value.length;i++)view.setUint8(offset+i,value.charCodeAt(i));};
 text(0,'RIFF');view.setUint32(4,36+samples*2,true);text(8,'WAVE');text(12,'fmt ');view.setUint32(16,16,true);view.setUint16(20,1,true);view.setUint16(22,1,true);view.setUint32(24,rate,true);view.setUint32(28,rate*2,true);view.setUint16(32,2,true);view.setUint16(34,16,true);text(36,'data');view.setUint32(40,samples*2,true);
 for(let i=0;i<samples;i++){const t=i/rate,fade=Math.min(1,t/1.7,(length-t)/2.4);let value=0;for(const [freq,amp] of [[130.8128,.2],[196,.12],[261.6256,.09],[329.6276,.06],[392,.035]])value+=Math.sin(2*Math.PI*freq*t+.18*Math.sin(2*Math.PI*.15*t))*amp;view.setInt16(44+i*2,Math.round(value*fade*(.72+.1*Math.sin(2*Math.PI*.12*t))*15000),true);}
 generatedAudioUrl=URL.createObjectURL(new Blob([buffer],{type:'audio/wav'}));audio.src=generatedAudioUrl;
}

function persist(){model.detailOpen=detailOpen;try{localStorage.setItem(storageKey,JSON.stringify(model));}catch{showToast('Browser storage unavailable. Edits are kept for this visit.');}}
function showToast(text){el('toast').textContent=text;el('toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el('toast').classList.remove('visible'),2600);}
function iconButton(name,label,attrs=''){return `<button class="icon-button" aria-label="${label}" ${attrs}>${icon(name)}</button>`;}
function backButton(label){return `<button class="back-button" data-back>${icon('back')}${label}</button>`;}
function switchApp(app){if(!['mail','notes','media','layout'].includes(app))return;model.app=app;detailOpen=false;searchText='';persist();render();}
document.querySelectorAll('[data-app]').forEach(b=>{b.querySelector('[data-icon]').innerHTML=icon(b.dataset.app==='notes'?'note':b.dataset.app==='media'?'play':b.dataset.app);b.addEventListener('click',()=>switchApp(b.dataset.app));});
document.querySelector('.wordmark').addEventListener('click',event=>{event.preventDefault();switchApp('mail');});
function render(){document.body.classList.toggle('large-text',model.largeText);document.body.classList.toggle('bounds-on',model.bounds);for(const button of document.querySelectorAll('[data-app]')){if(button.dataset.app===model.app)button.setAttribute('aria-current','page');else button.removeAttribute('aria-current');}const unread=mail.filter(m=>!model.read.includes(m.id)&&!model.archived.includes(m.id)).length;document.querySelector('.tab-count').textContent=unread;el('app-content').innerHTML=model.app==='mail'?mailView():model.app==='notes'?notesView():model.app==='media'?mediaView():layoutView();bindCommon();if(model.app==='mail')bindMail();if(model.app==='notes')bindNotes();if(model.app==='media')bindMedia();if(model.app==='layout')bindLayout();}
function getMail(){return [...mail,...model.sent];}
function selectedMessage(){return getMail().find(m=>m.id===model.selectedMail)||mail[0];}
function filteredMail(){return getMail().filter(m=>(model.mailFilter==='sent'?m.sent:model.mailFilter==='starred'?model.starred.includes(m.id)&&!model.archived.includes(m.id):!m.sent&&!model.archived.includes(m.id))&&`${m.name} ${m.subject} ${m.preview}`.toLowerCase().includes(searchText.toLowerCase()));}
function mailRows(){return filteredMail().map(m=>`<button class="mail-row ${m.id===model.selectedMail?'selected':''}" data-message="${escapeHTML(m.id)}" aria-label="Read ${escapeHTML(m.subject)}">${!m.sent&&!model.read.includes(m.id)?'<i class="unread-dot" aria-label="Unread"></i>':''}<span class="avatar ${m.color}">${escapeHTML(m.initials)}</span><span class="row-copy"><span class="row-top">${escapeHTML(m.name)}<time>${m.time}</time></span><h2>${escapeHTML(m.subject)}</h2><p>${escapeHTML(m.preview)}</p></span></button>`).join('')||'<p class="empty">No messages here yet.</p>';}
function mailView(){const m=selectedMessage();const hasSelection=filteredMail().some(row=>row.id===m.id);return `<section class="mail-view ${detailOpen?'show-detail':''}" aria-label="Mail example"><aside class="message-list"><div class="list-heading"><h1>${model.mailFilter==='sent'?'Sent':model.mailFilter==='starred'?'Starred':'Inbox'} <small>${filteredMail().length}</small></h1>${iconButton('compose','Compose message','data-compose')}</div><label class="search">${icon('search')}<input id="mail-search" type="search" placeholder="Search your inbox" aria-label="Search mail" value="${escapeHTML(searchText)}"></label><div class="list-filter">${[['inbox','Inbox'],['starred','Starred'],['sent','Sent']].map(([id,label])=>`<button data-filter="${id}" aria-pressed="${model.mailFilter===id}">${label}</button>`).join('')}</div><div id="mail-rows">${mailRows()}</div></aside>${!hasSelection?'<article class="detail"><p class="empty">Choose a message from this folder.</p></article>':`<article class="detail"><div class="detail-toolbar">${backButton('Inbox')}<span class="section-label">YOUR CONVERSATIONS</span>${iconButton('archive','Archive message','data-archive')}${iconButton('star',model.starred.includes(m.id)?'Unstar message':'Star message','data-star')}${iconButton('reply','Reply to message','data-reply')}</div><div class="message-body"><span class="eyebrow">${m.tag}</span><h1>${escapeHTML(m.subject)}</h1><div class="sender"><span class="avatar ${m.color}">${escapeHTML(m.initials)}</span><div><strong>${escapeHTML(m.name)}</strong><p>${m.sent?'to '+escapeHTML(m.recipient):'to you · Duo Studio'}</p></div><time>${m.time}</time></div><div class="letter">${m.paragraphs.map(p=>`<p>${p}</p>`).join('')}</div>${m.id==='mira'?`<button class="attachment" data-open-notes><span>NOTE</span><span><strong>Workspace review</strong><small>3 checkpoints · Open in Notes</small></span>${icon('note')}</button>`:''}<button class="reply" data-reply>${icon('reply')}Reply to ${escapeHTML(m.name.split(' ')[0])}</button></div></article>`}</section>`;}
function bindRows(){document.querySelectorAll('[data-message]').forEach(b=>b.addEventListener('click',()=>{model.selectedMail=b.dataset.message;if(!model.read.includes(model.selectedMail))model.read.push(model.selectedMail);detailOpen=true;persist();render();}));}
function bindCommon(){document.querySelectorAll('[data-back]').forEach(b=>b.addEventListener('click',()=>{detailOpen=false;render();}));document.querySelectorAll('[data-compose]').forEach(b=>b.addEventListener('click',()=>compose()));document.querySelectorAll('[data-open-notes]').forEach(b=>b.addEventListener('click',()=>{switchApp('notes');detailOpen=true;render();}));}
function bindMail(){bindRows();el('mail-search').addEventListener('input',event=>{searchText=event.target.value;el('mail-rows').innerHTML=mailRows();bindRows();});document.querySelectorAll('[data-filter]').forEach(b=>b.addEventListener('click',()=>{model.mailFilter=b.dataset.filter;searchText='';const matches=filteredMail();if(matches.length)model.selectedMail=matches[0].id;persist();render();}));document.querySelector('[data-star]')?.addEventListener('click',()=>{const id=selectedMessage().id;model.starred=model.starred.includes(id)?model.starred.filter(x=>x!==id):[...model.starred,id];persist();render();showToast(model.starred.includes(id)?'Added to Starred':'Removed from Starred');});document.querySelector('[data-archive]')?.addEventListener('click',()=>{const m=selectedMessage();if(m.sent){showToast('Sent messages stay in this demo’s Sent folder.');return;}model.archived.push(m.id);const next=filteredMail()[0];if(next)model.selectedMail=next.id;detailOpen=false;persist();render();showToast('Message archived · only this demo changed');});document.querySelectorAll('[data-reply]').forEach(b=>b.addEventListener('click',()=>{const m=selectedMessage();compose(m.sent?m.recipient:m.name.toLowerCase().split(' ')[0]+'@example.com','Re: '+m.subject);}));}
function compose(to='',subject=''){el('compose-to').value=to;el('compose-subject').value=subject;el('compose-body').value='';el('compose-dialog').showModal();el(to?'compose-body':'compose-to').focus();}
el('close-compose').addEventListener('click',()=>el('compose-dialog').close());
el('compose-form').addEventListener('submit',event=>{event.preventDefault();const subject=el('compose-subject').value.trim(),body=el('compose-body').value.trim();if(!subject||!body)return;const m={id:'sent-'+Date.now(),name:'You',initials:'AL',color:'blue',time:'Just now',subject,preview:body,tag:'SAVED TO SENT',recipient:el('compose-to').value,paragraphs:body.split('\n').filter(Boolean).map(escapeHTML),sent:true};model.sent.push(m);model.mailFilter='sent';model.selectedMail=m.id;persist();el('compose-dialog').close();detailOpen=true;render();showToast('Saved to demo Sent. No email was sent.');});
function selectedNote(){return model.notes.find(n=>n.id===model.selectedNote)||model.notes[0];}
function notesView(){const n=selectedNote();return `<section class="notes-view ${detailOpen?'show-detail':''}" aria-label="Notes example"><aside class="notes-list"><div class="list-heading"><h1>Notes <small>${model.notes.length}</small></h1>${iconButton('compose','Create note','data-new-note')}</div><label class="search">${icon('search')}<input id="note-search" type="search" placeholder="Find a thought" aria-label="Search notes"></label><div id="note-rows">${noteRows()}</div></aside><article class="detail"><div class="detail-toolbar">${backButton('Notes')}<span class="section-label">YOUR IDEAS, STILL HERE</span>${iconButton('compose','Create note','data-new-note')}</div><div class="notes-editor"><div class="note-meta"><span>Personal workspace</span><span id="save-status" role="status">Saved locally</span></div><input class="note-title" id="note-title" aria-label="Note title" value="${escapeHTML(n.title)}"><textarea class="note-text" id="note-text" aria-label="Note text">${escapeHTML(n.text)}</textarea>${n.checks.length?`<div class="note-checklist">${n.checks.map((c,i)=>`<label class="check-row"><input type="checkbox" data-check="${i}" ${c.done?'checked':''}><span>${escapeHTML(c.text)}</span></label>`).join('')}</div>`:''}<div class="note-callout">${icon('check')}<span>Try closing and reopening the phone. Your selected note and edits are saved in this browser.</span></div></div></article></section>`;}
function noteRows(){return model.notes.filter(n=>`${n.title} ${n.text}`.toLowerCase().includes(searchText.toLowerCase())).map(n=>`<button class="mail-row ${n.id===model.selectedNote?'selected':''}" data-note="${escapeHTML(n.id)}"><span class="row-copy"><h2 data-title-for="${escapeHTML(n.id)}">${escapeHTML(n.title)||'Untitled note'}</h2><p data-preview-for="${escapeHTML(n.id)}">${escapeHTML(n.text.split('\n').find(Boolean)||'A fresh page for a new idea.')}</p><div class="note-date">${n.checks.length?n.checks.filter(c=>c.done).length+' of '+n.checks.length+' complete':'Personal note'}</div></span></button>`).join('')||'<p class="empty">No matching notes.</p>';}
function bindNoteRows(){document.querySelectorAll('[data-note]').forEach(b=>b.addEventListener('click',()=>{model.selectedNote=b.dataset.note;detailOpen=true;persist();render();}));}
function bindNotes(){bindNoteRows();const update=()=>{detailOpen=true;const n=selectedNote();n.title=el('note-title').value;n.text=el('note-text').value;persist();el('save-status').textContent='Saved locally';const title=document.querySelector(`[data-title-for="${CSS.escape(n.id)}"]`);if(title)title.textContent=n.title||'Untitled note';const preview=document.querySelector(`[data-preview-for="${CSS.escape(n.id)}"]`);if(preview)preview.textContent=n.text.split('\n').find(Boolean)||'A fresh page for a new idea.';};el('note-title').addEventListener('input',update);el('note-text').addEventListener('input',update);el('note-search').addEventListener('input',event=>{searchText=event.target.value;el('note-rows').innerHTML=noteRows();bindNoteRows();});document.querySelectorAll('[data-check]').forEach(c=>c.addEventListener('change',()=>{selectedNote().checks[Number(c.dataset.check)].done=c.checked;detailOpen=true;persist();el('note-rows').innerHTML=noteRows();bindNoteRows();}));document.querySelectorAll('[data-new-note]').forEach(b=>b.addEventListener('click',()=>{const n={id:'note-'+Date.now(),title:'Untitled note',text:'',checks:[]};model.notes.unshift(n);model.selectedNote=n.id;detailOpen=true;persist();render();el('note-title').focus();el('note-title').select();}));}
function mediaView(){const t=tracks[trackIndex];return `<section class="media-view" aria-label="Media example"><div class="player-main"><div class="album-art" role="img" aria-label="Abstract blue water artwork"><div class="album-lettering"><span>DUO STUDIO</span><strong>${escapeHTML(t.title)}</strong><span>AMBIENT STUDIES / 01</span></div></div><div class="track-heading"><h1>${t.title}</h1><p>${t.artist}</p></div><div class="seek"><input type="range" id="seek" aria-label="Playback position" min="0" max="100" value="0"><div><span id="elapsed">0:00</span><span id="duration">0:${t.duration}</span></div></div><div class="player-controls"><button id="previous-track" aria-label="Previous track">${icon('previous')}</button><button class="play-button" id="play-audio" aria-label="${audio.paused?'Play':'Pause'} audio">${icon(audio.paused?'play':'pause')}</button><button id="next-track" aria-label="Next track">${icon('next')}</button></div></div><aside class="up-next"><span class="eyebrow">MADE FOR A SLOWER MOMENT</span><h2>A little breathing room.</h2><p>A quiet soundtrack, with the next track always in view.</p><div class="queue">${tracks.map((q,i)=>`<button data-track="${i}" class="${i===trackIndex?'active':''}" aria-label="Select ${q.title}"><span class="mini-art">${i+1}</span><span><strong>${q.title}</strong><small>${q.short}</small></span><span>0:${q.duration}</span></button>`).join('')}</div><p class="audio-note">Original synthesized demo audio. Three variations of one ambient loop. Playback starts when you tap Play.</p></aside></section>`;}
const timeLabel=n=>`${Math.floor(n/60)}:${String(Math.floor(n%60)).padStart(2,'0')}`;
function updatePlayback(){const control=el('play-audio');if(!control)return;control.innerHTML=icon(audio.paused?'play':'pause');control.setAttribute('aria-label',audio.paused?'Play audio':'Pause audio');const duration=Number.isFinite(audio.duration)?audio.duration:16;el('seek').value=String(duration?audio.currentTime/duration*100:0);el('elapsed').textContent=timeLabel(audio.currentTime/audio.playbackRate);el('duration').textContent=timeLabel(duration/audio.playbackRate);}
function selectTrack(index){const playing=!audio.paused;trackIndex=(index+tracks.length)%tracks.length;audio.playbackRate=tracks[trackIndex].rate;audio.preservesPitch=false;audio.currentTime=0;render();if(playing)audio.play().catch(()=>showToast('Tap Play to start the audio.'));}
function bindMedia(){el('play-audio').addEventListener('click',async()=>{if(audio.paused){try{prepareAudio();await audio.play();}catch{showToast('Audio could not start. Tap Play again or open the examples directly.');}}else audio.pause();updatePlayback();});el('seek').addEventListener('input',event=>{if(Number.isFinite(audio.duration))audio.currentTime=Number(event.target.value)/100*audio.duration;updatePlayback();});el('previous-track').addEventListener('click',()=>selectTrack(trackIndex-1));el('next-track').addEventListener('click',()=>selectTrack(trackIndex+1));document.querySelectorAll('[data-track]').forEach(b=>b.addEventListener('click',()=>selectTrack(Number(b.dataset.track))));updatePlayback();}
for(const event of ['timeupdate','loadedmetadata','play','pause'])audio.addEventListener(event,updatePlayback);
function viewport(){return {width:Math.round(document.documentElement.clientWidth),height:Math.round(document.documentElement.clientHeight)};}
function layoutView(){const v=viewport(),wide=v.width>620;return `<section class="layout-view" aria-label="Layout inspector"><div class="layout-heading"><div><h1>Room to adapt.</h1><p>Live measurements from this example’s web viewport.</p></div><span class="live-label">LIVE</span></div><div class="metric-grid"><div class="metric"><span>VIEWPORT WIDTH</span><strong id="metric-width">${v.width}<small>px</small></strong></div><div class="metric"><span>VIEWPORT HEIGHT</span><strong id="metric-height">${v.height}<small>px</small></strong></div><div class="metric"><span>APP NAVIGATION</span><strong id="metric-panes">${wide?'2 panes':'1 pane'}</strong></div></div><div class="layout-card"><div class="layout-diagram" aria-hidden="true"><div class="diagram-pane" id="diagram-list" ${wide?'':'hidden'}><i></i><i></i><i></i><i></i></div><div class="diagram-pane"><i></i><i></i></div></div><div class="layout-explanation"><h2 id="layout-mode">${wide?'Keep the context beside you.':'One task, with a clear way back.'}</h2><p>Mail and Notes use two panes above 620 CSS pixels. Below that content budget, the detail replaces the list and adds a Back button. Resize the browser window and watch these measurements change.</p></div></div><div class="layout-actions"><button id="toggle-bounds" aria-pressed="${model.bounds}">${model.bounds?'Hide':'Show'} layout bounds</button><button id="toggle-text" aria-pressed="${model.largeText}">${model.largeText?'Standard':'Larger'} reading text</button><button id="open-selection">Test note continuity →</button></div><p class="session-note">These are browser measurements and a web layout breakpoint. They do not report native size classes, safe areas, hinge angle, or reserved regions. Verify those in your native app.</p></section>`;}
function bindLayout(){el('toggle-bounds').addEventListener('click',()=>{model.bounds=!model.bounds;persist();render();});el('toggle-text').addEventListener('click',()=>{model.largeText=!model.largeText;persist();render();});el('open-selection').addEventListener('click',()=>{switchApp('notes');detailOpen=true;render();});}
new ResizeObserver(()=>{if(model.app==='layout'){const v=viewport(),wide=v.width>620;el('metric-width').innerHTML=`${v.width}<small>px</small>`;el('metric-height').innerHTML=`${v.height}<small>px</small>`;el('metric-panes').textContent=wide?'2 panes':'1 pane';el('diagram-list').hidden=!wide;el('layout-mode').textContent=wide?'Keep the context beside you.':'One task, with a clear way back.';}}).observe(document.documentElement);
window.addEventListener('storage',event=>{if(event.key!==storageKey)return;const focused=document.activeElement;const editing=document.hasFocus()&&focused&&(focused.matches('input,textarea')||el('compose-dialog').open);if(editing)return;restore();detailOpen=Boolean(model.detailOpen);render();});
render();
